-- ---------- Named checks (mirrored in src/server/enquiry.ts; the app's rules are at least as strict) ----------
do $$
declare t text;
begin
  foreach t in array array['enquiry_path', 'enquiry_type', 'enquiry_status'] loop
    execute format('alter table app.%I add constraint %I check (code ~ ''^[!-~]+( [!-~]+)*$'' and code = upper(code) and length(code) <= 30)', t, t || '_code_check');
    execute format('alter table app.%I add constraint %I check (name = btrim(name) and char_length(name) between 1 and 200)', t, t || '_name_check');
  end loop;
end $$;
alter table app.enquiry_status add constraint enquiry_status_kind_check check (kind in ('OPEN', 'ENROLLED', 'LOST', 'JUNK'));
alter table app.enquiry_status add constraint enquiry_status_colour_check check (colour ~ '^#[0-9a-f]{6}$');
alter table app.enquiry_status add constraint enquiry_status_sort_order_check check (sort_order between 0 and 1000);
-- exactly one ENROLLED status, the seeded one, always active (I3): code and kind are outside the update grant
alter table app.enquiry_status add constraint enquiry_status_enrolled_check check (kind <> 'ENROLLED' or (code = 'ENROLLED' and active));

-- The whitespace class is the set JS trim() removes, written out (as 0015).
do $$
declare
  ws constant text := '[\t\n\v\f\r    -     　﻿]';
  ctl constant text := '[\u0001-\u001f\u007f]';
  ctl_address constant text := '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]'; -- tab, newline, carriage return allowed
  c text; n int;
begin
  for c, n in select * from (values ('given_name', 100), ('family_name', 100), ('guardian_name', 100), ('instagram', 100),
      ('last_school', 100), ('current_address', 500), ('remark', 1000)) v(c, n) loop
    execute format('alter table app.enquiry add constraint %I check (%I !~ %L and %I !~ %L and %I !~ %L and char_length(%I) between 1 and %s)',
      'enquiry_' || c || '_check', c, '^' || ws, c, ws || '$', c, case when c in ('current_address', 'remark') then ctl_address else ctl end, c, n);
  end loop;
  foreach c in array array['mobile', 'whatsapp', 'landline', 'guardian_phone'] loop
    execute format('alter table app.enquiry add constraint %I check (%I ~ %L)', 'enquiry_' || c || '_check', c, '^[0-9]{10}$');
  end loop;
  execute format('alter table app.enquiry_followup add constraint enquiry_followup_note_check check (note !~ %L and note !~ %L and note !~ %L and char_length(note) between 1 and 2000)',
    '^' || ws, ws || '$', ctl_address);
end $$;
alter table app.enquiry add constraint enquiry_current_pincode_check check (current_pincode ~ '^[1-9][0-9]{5}$');
alter table app.enquiry add constraint enquiry_email_check check (email ~ '^[^@]*@[^@]*$'); -- exactly one @, as identityField
alter table app.enquiry add constraint enquiry_qualification_check
  check (qualification in ('BELOW_SSLC', 'SSLC', 'PLUS_TWO', 'DIPLOMA', 'DEGREE', 'POSTGRADUATE', 'OTHER', 'NOT_KNOWN'));
alter table app.enquiry add constraint enquiry_courses_check check ((course_code_3 is null or course_code_2 is not null)
  and (course_code_2 is null or course_code_2 <> course_code_1)
  and (course_code_3 is null or (course_code_3 <> course_code_1 and course_code_3 <> course_code_2)));
alter table app.enquiry add constraint enquiry_version_check check (version >= 1);
alter table app.enquiry_followup add constraint enquiry_followup_kind_check check (kind in ('CALL_IN', 'CALL_OUT', 'VISIT', 'MESSAGE', 'NOTE'));
alter table app.enquiry_followup add constraint enquiry_followup_duration_min_check check (duration_min between 0 and 600);

-- ---------- Guards (the database half of DD-6 and DD-15; refusals are P0001: the app checks first) ----------
-- They run as the caller: a status or parent the caller cannot see reads as missing and is refused (fail closed, R3).
create function app.enquiry_guard() returns trigger
language plpgsql set search_path = pg_catalog, app
as $$
declare k text;
begin
  select kind into k from app.enquiry_status where id = new.status_id;
  if tg_op = 'INSERT' then
    new.created_by := coalesce(app.session_user_id(), new.created_by); -- no function default under the drift gate (R2)
    new.created_at := now();
    if new.admission_id is not null or k is distinct from 'OPEN' or new.version <> 1 then
      raise exception 'enquiry must be inserted open, unenrolled, version 1';
    end if;
    return new;
  end if;
  if new.centre_id <> old.centre_id then
    raise exception 'enquiry centre cannot change';
  end if;
  if old.admission_id is not null then
    raise exception 'enquiry % is enrolled', old.id;
  end if;
  if (new.admission_id is not null) <> (k is not distinct from 'ENROLLED') then
    raise exception 'enquiry is enrolled exactly when it has an admission';
  end if;
  return new;
end $$;
create trigger enquiry_guard before insert or update on app.enquiry
  for each row execute function app.enquiry_guard();

create function app.enquiry_followup_guard() returns trigger
language plpgsql set search_path = pg_catalog, app
as $$
begin
  new.by_user := coalesce(app.session_user_id(), new.by_user);
  new.at := now();
  if not exists (select 1 from app.enquiry e where e.id = new.enquiry_id and e.centre_id = new.centre_id and e.admission_id is null) then
    raise exception 'follow-up needs an open, visible enquiry';
  end if;
  return new;
end $$;
create trigger enquiry_followup_guard before insert on app.enquiry_followup
  for each row execute function app.enquiry_followup_guard();
create trigger enquiry_followup_no_update_delete before update or delete on app.enquiry_followup
  for each row execute function app.ticket_immutable();
create trigger enquiry_followup_no_truncate before truncate on app.enquiry_followup
  for each statement execute function app.ticket_immutable();

-- ---------- RLS: view to read, manage to write, at the enquiry's centre (C1) ----------
do $$
declare t text;
begin
  foreach t in array array['enquiry', 'enquiry_followup'] loop
    execute format('alter table app.%I enable row level security', t);
    execute format('alter table app.%I force row level security', t);
    execute format('create policy %I on app.%I for select using (centre_id = any ((select app.scoped_centre_ids(''enquiry.view''))::int[]))', t || '_select', t);
    execute format('create policy %I on app.%I for insert with check (centre_id = any ((select app.scoped_centre_ids(''enquiry.manage''))::int[]))', t || '_insert', t);
    execute format('create policy %I on app.%I for update using (centre_id = any ((select app.scoped_centre_ids(''enquiry.manage''))::int[])) with check (centre_id = any ((select app.scoped_centre_ids(''enquiry.manage''))::int[]))', t || '_update', t);
    execute format('create policy %I on app.%I for delete using (centre_id = any ((select app.scoped_centre_ids(''enquiry.manage''))::int[]))', t || '_delete', t);
  end loop;
  -- masters: the 0012 setup pattern on enquiry.setup; no delete policy, rows are deactivated
  foreach t in array array['enquiry_path', 'enquiry_type', 'enquiry_status'] loop
    execute format('alter table app.%I enable row level security', t);
    execute format('alter table app.%I force row level security', t);
    execute format('create policy setup_select on app.%I for select using (true)', t);
    execute format('create policy setup_insert on app.%I for insert with check ((select app.has_permission(''enquiry.setup'', null)))', t);
    execute format('create policy setup_update on app.%I for update using ((select app.has_permission(''enquiry.setup'', null))) with check ((select app.has_permission(''enquiry.setup'', null)))', t);
  end loop;
end $$;

-- ---------- Grants (no delete anywhere; admission_id is written only by admit(), the guard enforces how) ----------
grant select, insert on app.enquiry, app.enquiry_followup, app.enquiry_path, app.enquiry_type, app.enquiry_status to gems_app;
grant update (name, active) on app.enquiry_path, app.enquiry_type to gems_app;
grant update (name, active, colour, sort_order) on app.enquiry_status to gems_app;
grant update (given_name, family_name, date_of_birth, gender, mobile, email, current_address, current_pincode, qualification,
  guardian_name, guardian_phone, whatsapp, landline, instagram, last_school, remark, path_id, type_id, status_id,
  course_code_1, course_code_2, course_code_3, counsellor_id, enquired_on, next_follow_up_on, last_contact_at, admission_id,
  version) on app.enquiry to gems_app;
grant usage on sequence app.enquiry_id_seq, app.enquiry_followup_id_seq, app.enquiry_path_id_seq, app.enquiry_type_id_seq,
  app.enquiry_status_id_seq to gems_app;

-- ---------- Definer functions (pattern of ticket_may_receive / ticket_people, 0009) ----------
-- May this user be given enquiries at this centre? Answers only callers who may view that centre's enquiries (C7).
create function app.enquiry_may_receive(p_centre int, p_user uuid) returns boolean
language sql stable security definer set search_path = pg_catalog, app
as $$
  select coalesce(app.has_permission('enquiry.view', p_centre), false)
     and exists (select 1 from app.app_user u where u.id = p_user and u.status = 'ACTIVE')
     and coalesce(p_centre = any (app.user_centre_ids(p_user, 'enquiry.manage')), false)
$$;
-- The counsellor picker for a centre.
create function app.enquiry_counsellors(p_centre int) returns table (id uuid, display_name text)
language sql stable security definer set search_path = pg_catalog, app
as $$
  select u.id, u.display_name from app.app_user u
  where u.status = 'ACTIVE' and app.enquiry_may_receive(p_centre, u.id)
  order by u.display_name, u.id
$$;
-- Names of the counsellors and follow-up authors of the given enquiries the caller may view (one call per page, D15).
create function app.enquiry_people(p_ids bigint[]) returns table (id uuid, display_name text)
language sql stable security definer set search_path = pg_catalog, app
as $$
  select u.id, u.display_name from app.app_user u
  where u.id in (
    select e.counsellor_id from app.enquiry e
      where e.id = any (p_ids) and e.centre_id = any (app.scoped_centre_ids('enquiry.view'))
    union
    select f.by_user from app.enquiry_followup f join app.enquiry e on e.id = f.enquiry_id and e.centre_id = f.centre_id
      where e.id = any (p_ids) and e.centre_id = any (app.scoped_centre_ids('enquiry.view')))
  order by u.display_name, u.id
$$;
revoke all on function app.enquiry_may_receive(int, uuid), app.enquiry_counsellors(int), app.enquiry_people(bigint[]) from public;
grant execute on function app.enquiry_may_receive(int, uuid), app.enquiry_counsellors(int), app.enquiry_people(bigint[]) to gems_app;

