-- ---------- Permissions; the system administrator holds every permission (0013) ----------
insert into app.permission (key, description, sensitive) values
  ('enquiry.view', 'View enquiries of a centre', false),
  ('enquiry.manage', 'Record and work enquiries of a centre', false),
  ('enquiry.setup', 'Maintain enquiry paths, types and statuses', true)
on conflict (key) do nothing;
insert into app.role_permission (role_id, permission_key)
  select r.id, p.key from app.role r cross join app.permission p where r.key = 'system_admin' and p.key like 'enquiry.%'
on conflict do nothing;
